package com.villofarm.model;
import com.fasterxml.jackson.annotation.JsonIgnore;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.ArrayList;import java.util.List;
@Entity @Table(name="customer_orders") public class CustomerOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(optional=false) @JsonIgnore private UserEntity customer;@Enumerated(EnumType.STRING) private OrderStatus status=OrderStatus.PLACED;private String paymentMethod="CASH_ON_DELIVERY";@Column(length=1000,nullable=false) private String deliveryAddress;private BigDecimal total=BigDecimal.ZERO;private Instant createdAt=Instant.now();@OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true) private List<OrderItem> items=new ArrayList<>();public Long getId(){return id;}public UserEntity getCustomer(){return customer;}public void setCustomer(UserEntity customer){this.customer=customer;}public String getCustomerName(){return customer.getName();}public OrderStatus getStatus(){return status;}public void setStatus(OrderStatus status){this.status=status;}public String getPaymentMethod(){return paymentMethod;}public void setPaymentMethod(String paymentMethod){this.paymentMethod=paymentMethod;}public String getDeliveryAddress(){return deliveryAddress;}public void setDeliveryAddress(String deliveryAddress){this.deliveryAddress=deliveryAddress;}public BigDecimal getTotal(){return total;}public void setTotal(BigDecimal total){this.total=total;}public Instant getCreatedAt(){return createdAt;}public List<OrderItem> getItems(){return items;}public void addItem(OrderItem item){items.add(item);item.setOrder(this);} }
